/**
 * Short sound and vibration cues for steps the user cannot watch (eyes closed, phone across the room): a single
 * "띵" when recording starts and a two-tone "띵동" plus a vibration when it ends (SRS-USA-012). Sound needs the audio
 * unlocked by a tap first (unlockCues on the start button). Vibration exists on Android browsers only, and is kept
 * off at the start so the phone on its stand does not shake while the step is being recorded.
 */
type AudioCtor = typeof AudioContext;
let ctx: AudioContext | null = null;

/** Creates or resumes the audio output; call from a tap (browsers keep audio locked until then). */
export function unlockCues(): void {
  try {
    const Ctor: AudioCtor | undefined = window.AudioContext ?? (window as unknown as { webkitAudioContext?: AudioCtor }).webkitAudioContext;
    if (!Ctor) return;
    ctx ??= new Ctor();
    void ctx.resume();
  } catch {
    ctx = null;
  }
}

function tones(freqs: readonly number[], dur = 0.13, gap = 0.05, level = 0.2): void {
  if (!ctx || ctx.state !== 'running') return;
  let t = ctx.currentTime + 0.01;
  for (const f of freqs) {
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = 'sine';
    o.frequency.value = f;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(level, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(ctx.destination);
    o.start(t);
    o.stop(t + dur + 0.02);
    t += dur + gap;
  }
}

function buzz(pattern: number[]): void {
  try {
    navigator.vibrate?.(pattern);
  } catch {
    /* not supported */
  }
}

/** Recording starts: one tone, no vibration (the phone must stay still). */
export function cueStart(sound: boolean): void {
  if (sound) tones([660]);
}

/** Recording is done: two rising tones and a short double vibration. */
export function cueEnd(sound: boolean): void {
  if (sound) tones([880, 1175]);
  buzz([70, 50, 70]);
}
