/**
 * Guided assessment protocol: alignment → rest → 5 standard movements
 * (Sunnybrook set) with countdown, timed recording, live quality feedback and
 * automatic repeat of steps with too few valid frames.
 *
 * Full assessment (default): six more expressions follow, and the same capture also runs the
 * synkinesis finder (FPA-SYNK), saved as a synk record linked to the session. Quick = the six only.
 */
import { useEffect, useMemo, useRef, useState } from 'preact/hooks';
import {
  AGGREGATION,
  MOVEMENT_TASKS,
  analyzeCoupling,
  analyzeMuscles,
  analyzeSession,
  autoSideTarget,
  buildRestReference,
  captureConditions,
  expressionMagnitude,
  liveFaceSize,
  placementHint,
  smileJawDrop,
  type PlacementHint,
  tasksNeedingRetry,
  type AnalysisResult,
  type CouplingExpression,
  type CouplingResult,
  type MuscleResult,
  type FrameObservation,
  type FrameQuality,
  type QualityIssue,
  type RestReference,
  type Side,
  type TaskId,
} from '../../core';
import { db } from '../../data/db';
import { APP_INFO, createSessionRecord, createSynkRecord } from '../../data/records';
import {
  RETAKE_COUNTDOWN,
  afterRejection,
  makeRejection,
  pickFrames,
  type RejectReason,
  type RejectionRecord,
} from '../../data/rejections';
import { drawSnapshot, saveSnapshots, toJpeg } from '../../data/snapshots';
import { actions, useApp } from '../../data/store';
import { AppBar, Notice } from '../components/common';
import { TaskExample, TaskExampleAnim } from '../components/TaskExample';
import { Icon } from '../icons';
import { CHANGE_FELT_LABEL, ISSUE_LABEL, REJECT_NOTE, SIDE_LABEL, TASK_INSTRUCTION, TASK_LABEL, WARNING_LABEL, fmtDate } from '../labels';
import type { PatientReport } from '../../data/types';
import { navigate } from '../router';
import { cueEnd, cueStart, unlockCues } from '../cues';
import { CameraStage, ghostFits, speak, speakAndWait, useFaceCamera, useWakeLock, type Ghost } from '../useFaceCamera';
import {
  CAPTURE_PACE_VERSION,
  PACE,
  PlateauStop,
  minMoveFrom,
  moveNoise,
  type MoveNoise,
  type StepCapture,
  type StopReason,
} from '../capturePace';
import { CaptureTracker, type Grabbed } from '../../vision/captureTracker';
import { METHOD_VERSION, methodOf, raftRunText, runRaft, saveRaftRun, withMethod, type RaftRun } from '../../vision/method';
import { HOW as SYNK_HOW, LABEL as SYNK_LABEL } from '../synk';

const STABLE_MS = 1500;
/** Without the voice, the instruction stays on screen this long before the count (time to read it). */
const READ_MS = 2500;
/** After two assessments the voice says only the step's name (and for the smile, teeth together). */
const SAY_SHORT: Record<TaskId, string> = {
  rest: '편안히 있기. 정면을 보세요.',
  brow: '이마 올리기.',
  eyeClose: '눈 살며시 감기.',
  smile: '이를 맞문 채 활짝 웃기.',
  snarl: '코 찡그리기.',
  pucker: '입술 오므리기.',
};

/** Expressions of the full assessment beyond the six standard ones (for the synkinesis finder). */
const EXTRA = ['eyeTight', 'smileClosed', 'oh', 'oo', 'frown', 'ee', 'lowerLip'] as const;
type Step = TaskId | (typeof EXTRA)[number];
type Mode = 'full' | 'quick';
const isTask = (s: Step): s is TaskId => s === 'rest' || (MOVEMENT_TASKS as readonly string[]).includes(s);
// Lower lip depression (depressor anguli oris / labii inferioris) is for the per-muscle detail only.
const stepLabel = (s: Step) => (isTask(s) ? TASK_LABEL[s] : s === 'lowerLip' ? '아랫입술 내리기' : SYNK_LABEL[s]);
const stepHow = (s: Step) =>
  isTask(s) ? TASK_INSTRUCTION[s] : s === 'lowerLip' ? '이를 가볍게 문 채 아랫입술을 아래로 내려 아랫니를 보이세요.' : SYNK_HOW[s];
/** What the voice says before a step (SRS-USA-013). */
const sayFor = (s: Step, returning: boolean) =>
  returning ? (isTask(s) ? SAY_SHORT[s] : `${stepLabel(s)}.`) : `${stepLabel(s)}. ${stepHow(s)}`;
const toMs = (sec: number | null) => (sec === null ? null : Math.round(sec * 1000));
const fullQueue = (m: Mode): Step[] => ['rest', ...MOVEMENT_TASKS, ...(m === 'full' ? EXTRA : [])];
/** Synkinesis finder expression ← assessment step. */
const COUPLING_FROM: Record<CouplingExpression, Step> = {
  brow: 'brow',
  eyeGentle: 'eyeClose',
  eyeTight: 'eyeTight',
  smileClosed: 'smileClosed',
  pucker: 'pucker',
  oh: 'oh',
  oo: 'oo',
  frown: 'frown',
  ee: 'ee',
};
const COUPLING_STEPS = new Set<Step>(Object.values(COUPLING_FROM));
/** Steps whose spread frames are kept (synkinesis finder, and the two muscle items outside the six). */
const SPREAD_STEPS = new Set<Step>([...COUPLING_STEPS, 'lowerLip']);
/** Candidate frames kept per step for its photo (as many as the analysis' peak frames). */
const PHOTO_POOL = 12;
/** Warnings the result screen shows as their own cards (with an action). */
const HANDLED = new Set(['LOW_EFFORT', 'SIDE_MISMATCH', 'HIGH_ALIGNMENT_RESIDUAL']);

type Phase =
  | { k: 'intro' }
  | { k: 'align' }
  /**
   * `note` = why the step is retaken; `example` = show the animated example first; `say` = what the voice says
   * instead of the step's instruction (SRS-QC-006).
   */
  | { k: 'countdown'; i: number; n: number; note?: string; example?: boolean; say?: string; ready?: boolean }
  | { k: 'record'; i: number; start: number }
  | { k: 'relax'; i: number }
  | { k: 'analyzing' }
  | { k: 'result'; r: AnalysisResult; c: CouplingResult | null; m: MuscleResult }
  | { k: 'saving' };

function topIssue(counts: Partial<Record<QualityIssue, number>>): QualityIssue | null {
  const e = Object.entries(counts).sort((a, b) => (b[1] ?? 0) - (a[1] ?? 0))[0];
  return e ? (e[0] as QualityIssue) : null;
}

export function Assess() {
  const { profile, sessions } = useApp();
  const [phase, setPhase] = useState<Phase>({ k: 'intro' });
  // The previous assessment's face position: dashed outline and distance hint so sessions are shot alike (QC-008).
  const prevScored = useMemo(() => [...sessions].reverse().find((x) => x.analysis.keyframes), [sessions.length]);
  const prevCond = useMemo(() => captureConditions(prevScored?.analysis), [prevScored]);
  const ghost = useMemo<Ghost | null>(() => {
    const k = prevScored?.analysis.keyframes;
    return k && k.rest.length >= 2 * 478 ? { width: k.width, height: k.height, pts: k.rest } : null;
  }, [prevScored]);
  const [place, setPlace] = useState<PlacementHint | null>(null);
  const [ghostShown, setGhostShown] = useState(false);
  // Felt change since the last assessment, asked on the result screen before any numbers are shown (optional).
  const [felt, setFelt] = useState<PatientReport['changeSinceLast'] | null>(null);
  // The side the analysis switched to on its own (a clearly weaker other side), and the user's 'keep my setting'.
  const [autoSide, setAutoSide] = useState<{ from: Side; to: Side } | null>(null);
  const keepSide = useRef(false);
  const placeN = useRef(0);
  const [mode, setMode] = useState<Mode>('full');
  const [queue, setQueue] = useState<Step[]>(fullQueue('full'));
  const [progress, setProgress] = useState(0);
  const frames = useRef<Partial<Record<TaskId, FrameObservation[]>>>({});
  // Frames spread over each recording for the synkinesis finder (it correlates regions over time).
  const cframes = useRef<Partial<Record<Step, FrameObservation[]>>>({});
  // Raw detections per task, for the tracking-vs-detection comparison (window.__assessDebug, kv 'assessDebug').
  const raw = useRef<Partial<Record<TaskId, FrameObservation[]>>>({});
  const rec = useRef<{
    task: Step;
    frames: FrameObservation[];
    grabbed: Grabbed[];
    valid: number;
    issues: Partial<Record<QualityIssue, number>>;
  } | null>(null);
  // Landmarks are tracked from the first valid rest frame (FPA-GEOM 0.3.0); detections are the fallback.
  const method = methodOf(profile);
  const tracker = useRef<CaptureTracker>(null as unknown as CaptureTracker);
  tracker.current ??= new CaptureTracker(method);
  // SEA-RAFT hybrid (research setting): progress while it runs, and what it took (shown with the result).
  const [raftMsg, setRaftMsg] = useState<string | null>(null);
  const raftRun = useRef<RaftRun | null>(null);
  // Optional photos (profile.savePhotos). While a step records, up to PHOTO_POOL candidate frames are kept
  // (rest: spread over the recording; task: the most expressive); when it ends one is chosen like the analysis'
  // keyframe: the held expression (closest to the median of the peak frames), rest: the most neutral frame.
  const pool = useRef<Partial<Record<Step, { c: HTMLCanvasElement; obs: FrameObservation; score: number }[]>>>({});
  const shots = useRef<Partial<Record<Step, HTMLCanvasElement>>>({});
  const restRef = useRef<RestReference | null>(null);
  const restSeen = useRef(0);
  const stableSince = useRef<number | null>(null);
  const repeats = useRef(0);
  // Rejected attempts of the current step, logged when the step is decided (data/rejections.ts, SRS-DAT-012).
  const rejected = useRef<RejectionRecord[]>([]);
  // Recording pace (SRS-USA-013): the rest step's movement noise, the running stop of the step being recorded, a tap
  // asking to end it, and what each step took (kept with the record).
  const restMove = useRef<MoveNoise | null>(null);
  const pace = useRef<{ stop: PlateauStop; done: StopReason | null } | null>(null);
  const recStart = useRef(0);
  const paceN = useRef(0);
  const tapped = useRef(false);
  const capture = useRef<Partial<Record<Step, StepCapture>>>({});
  const relaxSaid = useRef<Promise<void>>(Promise.resolve());
  const returning = useMemo(
    () => sessions.filter((x) => x.mode === 'video' && x.analysis.status === 'complete').length >= 2,
    [sessions.length],
  );
  const voice = profile?.voiceGuide ?? true;
  const cameraOn = phase.k !== 'intro' && phase.k !== 'analyzing' && phase.k !== 'result' && phase.k !== 'saving';
  const guiding = !!prevCond && (phase.k === 'align' || ('i' in phase && queue[phase.i] === 'rest' && phase.k !== 'relax'));

  const onFrame = (obs: FrameObservation, q: FrameQuality, src: HTMLVideoElement) => {
    if (rec.current) {
      rec.current.frames.push(obs);
      if (q.ok) {
        rec.current.valid++;
        const tk = tracker.current;
        if (rec.current.task === 'rest' && !tk.ref) tk.setRef(src, obs);
        const gray = tk.grab(src, obs, rec.current.task);
        if (gray) rec.current.grabbed.push({ obs, gray });
        if (profile?.savePhotos) keepShot(rec.current.task, obs, src);
      }
      for (const i of q.issues) rec.current.issues[i] = (rec.current.issues[i] ?? 0) + 1;
      // The step ends once the expression is held at its peak (capturePace.ts).
      const pc = pace.current;
      if (pc && !pc.done && restRef.current) {
        const f = pc.stop.feed((performance.now() - recStart.current) / 1000, q.ok ? expressionMagnitude(restRef.current, obs) : null);
        if (f.done) pc.done = f.reason ?? 'plateau';
        if (++paceN.current % 3 === 0 || f.done) setProgress(f.hold);
      }
    }
    stableSince.current = q.ok ? (stableSince.current ?? performance.now()) : null;
    // Same distance as last time: live hint while lining up and during the rest step.
    if (prevCond && guiding && ++placeN.current % 5 === 0) {
      const size = liveFaceSize(obs);
      const h = size ? placementHint(size, prevCond) : null;
      if (h !== place) setPlace(h);
      const shown = !!ghost && ghostFits(ghost, obs.width, obs.height);
      if (shown !== ghostShown) setGhostShown(shown);
    }
  };
  const keepShot = (step: Step, obs: FrameObservation, src: HTMLVideoElement) => {
    const cands = (pool.current[step] ??= []);
    if (step === 'rest') {
      if (restSeen.current++ % 3 !== 0 || cands.length >= PHOTO_POOL) return;
      const c = drawSnapshot(src);
      if (c) cands.push({ c, obs, score: 0 });
      return;
    }
    if (!isTask(step) || !restRef.current) return;
    const score = expressionMagnitude(restRef.current, obs);
    if (score === null) return;
    if (cands.length < PHOTO_POOL) {
      const c = drawSnapshot(src);
      if (c) cands.push({ c, obs, score });
      return;
    }
    const low = cands.reduce((m, x, i) => (x.score < cands[m]!.score ? i : m), 0);
    if (score <= cands[low]!.score) return;
    if (drawSnapshot(src, cands[low]!.c)) cands[low] = { c: cands[low]!.c, obs, score };
  };
  /** The step's photo once its recording ends: the held expression, or the most neutral rest frame. */
  const choosePhoto = (step: Step) => {
    const cands = pool.current[step] ?? [];
    delete pool.current[step];
    if (!cands.length) return;
    if (step === 'rest') {
      const ref = restRef.current;
      const d = (o: FrameObservation) => (ref ? (expressionMagnitude(ref, o) ?? Infinity) : 0);
      shots.current.rest = cands.reduce((b, x) => (d(x.obs) < d(b.obs) ? x : b)).c;
      return;
    }
    const sorted = cands.map((x) => x.score).sort((a, b) => a - b);
    const med = sorted[Math.floor(sorted.length / 2)]!;
    shots.current[step] = cands.reduce((b, x) => (Math.abs(x.score - med) < Math.abs(b.score - med) ? x : b)).c;
  };
  const cam = useFaceCamera(cameraOn, onFrame, guiding ? ghost : null);
  useWakeLock(cameraOn);

  // Alignment: auto-start once the face has been continuously acceptable.
  useEffect(() => {
    if (phase.k !== 'align' || cam.status !== 'ready') return;
    speak(
      '얼굴을 화면 가운데에 맞추고 정면을 바라보세요. 안내가 끝나고 셋을 세면 띵 소리가 납니다. 표정을 가장 크게 지은 채 잠깐 버티면 띵동 소리와 진동으로 끝납니다. 준비되면 자동으로 시작합니다.',
      voice,
    );
    const id = setInterval(() => {
      const s = stableSince.current;
      setProgress(s ? Math.min(1, (performance.now() - s) / STABLE_MS) : 0);
      if (s && performance.now() - s >= STABLE_MS) {
        clearInterval(id);
        setPhase({ k: 'countdown', i: 0, n: 3 });
      }
    }, 100);
    return () => clearInterval(id);
  }, [phase.k, cam.status]);

  useEffect(() => {
    if (phase.k === 'countdown') {
      // The instruction is said first and the count starts once it has been said, so it never runs into the
      // recording (SRS-USA-013). A retake says why and what to do in one go.
      if (!phase.ready) {
        let live = true;
        const text = phase.say ?? sayFor(queue[phase.i]!, returning);
        const said = voice ? speakAndWait(text, true) : new Promise<void>((r) => setTimeout(r, READ_MS));
        void said.then(() => live && setPhase({ ...phase, ready: true }));
        return () => {
          live = false;
        };
      }
      const id = setTimeout(() => {
        if (phase.n > 1) setPhase({ ...phase, n: phase.n - 1 });
        else startRecord(phase.i);
      }, 1000);
      return () => clearTimeout(id);
    }
    if (phase.k === 'record') {
      const task = queue[phase.i]!;
      const id = setInterval(() => {
        const sec = (performance.now() - phase.start) / 1000;
        const pc = pace.current;
        // Rest records a fixed stretch; an expression ends once held at its peak, after maxSec at the latest, or on a tap.
        let reason: StopReason | null = null;
        if (!pc) {
          setProgress(Math.min(1, sec / PACE.restSec));
          if (sec >= PACE.restSec) reason = 'fixed';
        } else reason = tapped.current ? 'tap' : (pc.done ?? (sec >= PACE.maxSec ? 'max' : null));
        if (!reason) return;
        clearInterval(id);
        cueEnd(voice);
        capture.current[task] = { ms: Math.round(sec * 1000), reason, toPeakMs: pc ? toMs(pc.stop.timeToPeak()) : null };
        pace.current = null;
        const r = rec.current!;
        rec.current = null;
        const tk = tracker.current;
        // A rejected step is retaken once, with the animated example first; a second rejection moves on. Every
        // rejected attempt goes to the rejection log, to find out later why steps fail (SRS-QC-006, SRS-DAT-012).
        const reject = (reason: RejectReason, shown: readonly FrameObservation[], jawDrop?: number): boolean => {
          const next = afterRejection(repeats.current);
          rejected.current.push(
            makeRejection({
              step: task,
              attempt: repeats.current + 1,
              reason,
              movedOn: next === 'moveOn',
              validFrames: r.valid,
              totalFrames: r.frames.length,
              issues: r.issues,
              jawDrop,
              jawLimit: AGGREGATION.maxJawDrop,
              app: { version: APP_INFO.version, algorithm: METHOD_VERSION[method] },
              rest: tk.ref?.obs ?? null,
              frames: shown,
            }),
          );
          if (next === 'moveOn') return false;
          repeats.current++;
          tk.resetTask(task);
          const issue = topIssue(r.issues);
          setPhase({
            k: 'countdown',
            i: phase.i,
            n: RETAKE_COUNTDOWN,
            note: reason === 'jawOpen' ? REJECT_NOTE.jawOpen : issue ? ISSUE_LABEL[issue] : REJECT_NOTE.fewFrames,
            example: true,
            say: reason === 'jawOpen' ? '턱이 벌어졌어요. 그림처럼 이를 맞문 채 웃어 주세요.' : `다시 한 번 하겠습니다. ${stepHow(task)}`,
          });
          return true;
        };
        if (r.valid < AGGREGATION.minValidFrames.video && reject('fewFrames', pickFrames(r.frames))) return;
        try {
          if (task === 'rest') {
            restRef.current = buildRestReference(r.frames);
            // How much a still face 'moves' between frames: an expression has to clear it to count as started.
            const ref = restRef.current;
            restMove.current = ref ? moveNoise(r.frames.flatMap((o) => expressionMagnitude(ref, o) ?? [])) : null;
          }
          if (profile?.savePhotos) choosePhoto(task);
          if (isTask(task)) raw.current[task] = r.frames;
          if (isTask(task)) frames.current[task] = tk.trackTask(task, r.frames, r.grabbed);
          if (mode === 'full' && SPREAD_STEPS.has(task)) cframes.current[task] = tk.trackEven(r.frames, r.grabbed, 16, `spread:${task}`);
        } catch (e) {
          console.warn('tracking failed, using detections', e);
          if (isTask(task)) frames.current[task] = r.frames;
          if (SPREAD_STEPS.has(task)) cframes.current[task] = r.frames;
        }
        // Smile with the teeth together: a lowered chin (jaw opened) is rejected (SRS-QC-009). Same rest frame (the
        // tracker's reference = the analysis' first rest frame) and frames as the analysis, so both read the same.
        if (task === 'smile' && tk.ref) {
          const jaw = smileJawDrop(tk.ref.obs, frames.current.smile ?? []);
          if (jaw && jaw.drop > AGGREGATION.maxJawDrop && reject('jawOpen', jaw.frames, jaw.drop)) return;
        }
        repeats.current = 0;
        if (rejected.current.length) void actions.addRejections(rejected.current.splice(0));
        // The next instruction waits for this line, so 'eyes open' is never cut off.
        relaxSaid.current =
          task === 'eyeClose' || task === 'eyeTight'
            ? speakAndWait('눈을 뜨고 힘을 빼세요.', voice)
            : task !== 'rest'
              ? speakAndWait('힘을 빼세요.', voice)
              : Promise.resolve();
        setPhase({ k: 'relax', i: phase.i });
      }, 50);
      return () => clearInterval(id);
    }
    if (phase.k === 'relax') {
      let live = true;
      void Promise.all([relaxSaid.current, new Promise((r) => setTimeout(r, 1400))]).then(() => {
        if (!live) return;
        if (phase.i + 1 < queue.length) setPhase({ k: 'countdown', i: phase.i + 1, n: 3 });
        else setPhase({ k: 'analyzing' });
      });
      return () => {
        live = false;
      };
    }
    if (phase.k === 'analyzing') {
      // The camera is off now (the mirror step switches the landmarker to image mode).
      let live = true;
      void (async () => {
        await new Promise((r) => setTimeout(r, 150));
        try {
          const { getEngine } = await import('../../vision/landmarker');
          const engine = await getEngine(() => {});
          const detect = (c: HTMLCanvasElement) => engine.detectImage(c);
          // FPA-GEOM 0.5.0: eyes whose lid points were not tracked are measured on their mirror composites.
          await tracker.current.addMirror('eyeClose', detect);
          if (mode === 'full') await tracker.current.addMirror('spread:eyeTight', detect);
        } catch (e) {
          console.warn('eye mirror step skipped', e);
        }
        if (method === 'raft') raftRun.current = await runRaft(tracker.current, (s) => live && setRaftMsg(s));
        if (live) finish();
      })();
      return () => {
        live = false;
      };
    }
    return undefined;
  }, [phase]);

  /** Starts recording step `i` (after the count, or at once on a tap). */
  const startRecord = (i: number) => {
    const step = queue[i]!;
    if (step === 'rest') tracker.current.reset();
    // A repeated step starts its photo over.
    delete shots.current[step];
    delete pool.current[step];
    if (step === 'rest') restSeen.current = 0;
    rec.current = { task: step, frames: [], grabbed: [], valid: 0, issues: {} };
    tapped.current = false;
    pace.current = step === 'rest' ? null : { stop: new PlateauStop(minMoveFrom(restMove.current)), done: null };
    recStart.current = performance.now();
    setProgress(0);
    cueStart(voice);
    setPhase({ k: 'record', i, start: recStart.current });
  };

  /** A tap on the camera: skip the instruction and count, or end an expression that is already held (SRS-USA-013). */
  const onStageTap = () => {
    if (phase.k === 'countdown') {
      if (typeof speechSynthesis !== 'undefined') speechSynthesis.cancel();
      startRecord(phase.i);
    } else if (phase.k === 'record' && pace.current && (performance.now() - phase.start) / 1000 >= PACE.tapAfterSec) tapped.current = true;
  };

  /** Analyses what was captured; `side` re-runs it for the other affected side (setting corrected). */
  const finish = (side: Side = profile!.affectedSide, switchedFrom: Side | null = null) => {
    const f = frames.current;
    const used = method === 'raft' && raftRun.current?.error ? 'v060' : method;
    const r = withMethod(
      analyzeSession({
        affectedSide: side,
        mode: 'video',
        rest: f.rest ?? [],
        tasks: Object.fromEntries(MOVEMENT_TASKS.map((t) => [t, f[t] ?? []])),
      }),
      used,
    );
    // A clearly weaker other side means the setting is probably wrong (the healthy side measured as the paralysed one):
    // recalculate with the measured side, then ask on the result screen (SRS-ALG-011).
    const target = switchedFrom || keepSide.current ? null : autoSideTarget(r);
    if (target) return finish(target, side);
    try {
      // Same analysis on the raw detections: tells a tracking failure from a real lack of movement.
      const d = analyzeSession({
        affectedSide: side,
        mode: 'video',
        rest: raw.current.rest ?? [],
        tasks: Object.fromEntries(MOVEMENT_TASKS.map((t) => [t, raw.current[t] ?? []])),
      });
      const pick = (a: AnalysisResult) =>
        Object.fromEntries(Object.entries(a.tasks).map(([t, v]) => [t, { ratio: v?.ratio ?? null, exc: v?.excursion ?? null }]));
      const dbg = { at: new Date().toISOString(), mode, method, raft: raftRun.current, tracked: pick(r), detected: pick(d) };
      (window as unknown as { __assessDebug?: unknown }).__assessDebug = dbg;
      // Also kept on the device (last 5, not part of the sealed record) so a reload does not lose it.
      void db
        .getKv<unknown[]>('assessDebug')
        .then((prev) => db.setKv('assessDebug', [...(prev ?? []), dbg].slice(-5)))
        .catch((e) => console.warn('debug save failed', e));
    } catch (e) {
      console.warn('debug comparison failed', e);
    }
    const c =
      mode === 'full'
        ? analyzeCoupling({
            affectedSide: side,
            rest: f.rest ?? [],
            expressions: Object.fromEntries(
              (Object.entries(COUPLING_FROM) as [CouplingExpression, Step][]).map(([e, st]) => [e, cframes.current[st] ?? []]),
            ),
          })
        : null;
    const m = analyzeMuscles({
      affectedSide: side,
      rest: f.rest ?? [],
      expressions: {
        brow: f.brow,
        eyeGentle: f.eyeClose,
        eyeTight: cframes.current.eyeTight,
        smile: f.smile,
        snarl: f.snarl,
        lowerLip: cframes.current.lowerLip,
        pucker: f.pucker,
      },
    });
    const done = r.status === 'complete' ? '측정이 끝났습니다.' : '일부 동작을 다시 측정해야 합니다.';
    speak(
      switchedFrom
        ? `${done} 측정해 보니 ${SIDE_LABEL[side]}이 뚜렷하게 약해서 ${SIDE_LABEL[side]}을 마비 쪽으로 계산했습니다. 화면에서 확인해 주세요.`
        : done,
      voice,
    );
    setAutoSide(switchedFrom ? { from: switchedFrom, to: side } : null);
    setPhase({ k: 'result', r, c, m });
  };

  const save = async (r: AnalysisResult, c: CouplingResult | null, m: MuscleResult | null) => {
    setPhase({ k: 'saving' });
    const record = await createSessionRecord({
      analysis: r,
      ...(m ? { muscles: m } : {}),
      ...(felt !== null ? { patientReport: { changeSinceLast: felt } } : {}),
      profile: profile!,
      mode: 'video',
      engine: cam.engine()?.info ?? null,
      camera: cam.cameraLabel(),
      capture: { version: CAPTURE_PACE_VERSION, steps: capture.current },
    });
    await actions.addSession(record);
    if (raftRun.current) await saveRaftRun(record.id, raftRun.current);
    if (profile!.savePhotos && Object.keys(shots.current).length) {
      try {
        const items: Record<string, { blob: Blob; w: number; h: number }> = {};
        for (const [step, c] of Object.entries(shots.current)) {
          const blob = c && (await toJpeg(c));
          if (blob) items[step] = { blob, w: c.width, h: c.height };
        }
        await saveSnapshots({ id: record.id, createdAt: record.createdAt, items });
      } catch (e) {
        console.warn('photos not saved', e); // the measurement itself is saved
      }
    }
    if (c && c.status !== 'failed') {
      const engine = cam.engine()?.info ?? null;
      await actions.addSynk(
        await createSynkRecord({ result: c, profile: profile!, engine, camera: cam.cameraLabel(), sessionId: record.id }),
      );
    }
    navigate(`/session/${record.id}`);
  };

  const start = (m: Mode) => {
    setMode(m);
    setFelt(null);
    setAutoSide(null);
    keepSide.current = false;
    setQueue(fullQueue(m));
    frames.current = {};
    cframes.current = {};
    raw.current = {};
    shots.current = {};
    pool.current = {};
    restRef.current = null;
    restMove.current = null;
    capture.current = {};
    unlockCues();
    setPhase({ k: 'align' });
  };

  const restart = (tasks: Step[]) => {
    setQueue(tasks);
    stableSince.current = null;
    unlockCues();
    setPhase({ k: 'align' });
  };

  if (!profile) return null;
  const isDemo = !!(profile.demo || profile.demoCaseId);
  const resetToOwnProfile = async () => {
    if (!confirm('예시(데모) 기록을 모두 지우고 내 정보로 새로 시작합니다. 계속할까요?')) return;
    await actions.deleteAll();
    navigate('/');
  };
  /** The measurement says the other side is weaker: correct the setting and re-run the analysis on the same frames. */
  const switchSide = async (to: Side) => {
    await actions.saveProfile({ ...profile, affectedSide: to });
    finish(to);
  };

  const lastScored = [...sessions].reverse().find((x) => x.analysis.keyframes);
  const lastCond = captureConditions(lastScored?.analysis);

  if (phase.k === 'intro') {
    return (
      <>
        <AppBar title="얼굴 움직임 평가" sub="정밀 약 1분 50초 · 빠른 평가 약 1분" />
        <main class="main">
          {isDemo && (
            <div class="card warn">
              <Notice tone="warn">
                <b>지금은 예시(데모) 프로필입니다 · 마비 쪽 {SIDE_LABEL[profile.affectedSide]}</b>
                <div class="small">
                  이대로 찍으면 결과가 예시 설정으로 계산되어 맞지 않을 수 있습니다. 직접 측정하려면 먼저 내 정보(마비 쪽)로 새로
                  시작하세요.
                </div>
              </Notice>
              <button class="btn primary block" onClick={resetToOwnProfile}>
                데모 지우고 내 프로필 만들기
              </button>
            </div>
          )}
          <div class="card">
            <h2>촬영 전 확인해 주세요</h2>
            <ul class="stack small ink2" style={{ margin: 0, paddingLeft: '20px' }}>
              <li>얼굴 정면에서 빛이 고르게 비치는 밝은 곳에서 촬영하세요. 창문을 옆에 두지 마세요.</li>
              <li>안경을 벗고, 앞머리가 눈썹을 가리지 않게 넘겨 주세요.</li>
              <li>휴대폰을 눈높이에 세워 두고, 얼굴에서 30~40cm 떨어지세요. 거치대를 권장합니다.</li>
              <li>화면 안내와 음성에 따라 표정을 차례로 짓습니다. 표정마다 3초간 유지하세요.</li>
              <li>
                <b>정밀 평가</b>는 기본 6가지 뒤에 연합운동과 근육별 움직임을 보는 표정 7가지(눈 꽉 감기, 입 다물고 미소, 오, 우, 미간
                찡그리기, 이, 아랫입술 내리기)가 이어집니다. 움직임 점수, 근육별 상세, 연합운동 지도를 한 번에 봅니다.
              </li>
            </ul>
          </div>
          <div class="card">
            <h3>이렇게 따라 하세요</h3>
            <div class="task-examples">
              {(['rest', ...MOVEMENT_TASKS] as const).map((t) => (
                <figure>
                  <div class="fsr-thumb">
                    <TaskExample task={t} affectedSide={profile.affectedSide} />
                  </div>
                  <figcaption class="xsmall">{TASK_LABEL[t]}</figcaption>
                </figure>
              ))}
            </div>
            <p class="xsmall muted">
              마비 쪽이 덜 움직여도 괜찮습니다. 양쪽 모두 그림처럼 최대한 움직이려고 해 보세요(눈 감기는 힘주지 않고).
            </p>
          </div>
          {lastCond && (
            <div class="card tight">
              <Notice>
                <span class="small">
                  지난 평가({fmtDate(lastScored!.createdAt)})와 <b>같은 자리·같은 거리·같은 조명</b>에서 찍어야 비교가 정확합니다.
                  지난번에는 얼굴이 화면 폭의 약 {Math.round(lastCond.faceSize * 100)}%를 차지했습니다. 거리가 다르면 촬영 화면에서 앞뒤로
                  움직이라고 알려 드리고, 같은 폰 카메라라면 지난번 얼굴 자리를 파란 점선으로 보여 드립니다.
                </span>
              </Notice>
            </div>
          )}
          <div class="card tight">
            <Notice>
              <span class="small">
                {profile.savePhotos
                  ? '영상은 이 기기 안에서만 분석됩니다. 사진 저장이 켜져 있어 동작마다 사진 1장씩이 이 폰에만 저장됩니다(전송 없음, 설정에서 끄거나 지울 수 있음).'
                  : '영상은 이 기기 안에서만 분석되며 저장되지 않습니다. 얼굴 점 좌표와 측정값만 기록됩니다.'}
              </span>
            </Notice>
          </div>
          <button class="btn primary block" onClick={() => start('full')}>
            <Icon name="camera" /> 정밀 평가 시작 (13가지 표정 · 근육별 · 연합운동)
          </button>
          <button class="btn block" onClick={() => start('quick')}>
            빠른 평가 (6가지 표정 · 약 1분)
          </button>
          <a class="btn ghost block" href="#/upload">
            <Icon name="upload" /> 이미 찍은 사진·영상으로 평가
          </a>
        </main>
      </>
    );
  }

  if (phase.k === 'analyzing') {
    return (
      <>
        <AppBar title="측정 결과 확인" />
        <main class="main">
          <div class="card center">
            <b>분석 중…</b>
            <p class="small ink2" style={{ margin: '4px 0 0' }}>
              {raftMsg ?? '눈 감김은 한쪽씩 다시 확인하고 있습니다(1~2초).'}
            </p>
          </div>
        </main>
      </>
    );
  }

  if (phase.k === 'result' || phase.k === 'saving') {
    const r = phase.k === 'result' ? phase.r : null;
    const retry = r ? tasksNeedingRetry(r) : [];
    const suggested = r?.warnings.some((w) => w.code === 'SIDE_MISMATCH') ? r.suggestedAffectedSide : undefined;
    // Tasks where the head moved (alignment residual) and that are not already in the retry list.
    const moved = [
      ...new Set((r?.warnings ?? []).flatMap((w) => (w.code === 'HIGH_ALIGNMENT_RESIDUAL' && w.task && w.task !== 'rest' ? [w.task] : []))),
    ].filter((t) => !retry.includes(t as (typeof retry)[number])) as TaskId[];
    // Smile taken with the jaw open (it moved on after two rejections): offer the smile alone again.
    const jawOpen = !!r?.warnings.some((w) => w.code === 'JAW_OPEN') && !retry.includes('smile') && !moved.includes('smile');
    const doSave = () => save(r!, phase.k === 'result' ? phase.c : null, phase.k === 'result' ? phase.m : null);
    return (
      <>
        <AppBar title="측정 결과 확인" />
        <main class="main">
          {!r && <div class="card center">저장 중…</div>}
          {r && raftRun.current && (
            <div class="card">
              <Notice tone={raftRun.current.error ? 'warn' : undefined}>
                <span class="small">{raftRunText(raftRun.current)}</span>
              </Notice>
            </div>
          )}
          {r && autoSide && (
            <div class="card warn">
              <Notice tone="warn">
                <b>
                  측정해 보니 {SIDE_LABEL[autoSide.to]}이 뚜렷하게 약해서 {SIDE_LABEL[autoSide.to]}을 마비 쪽으로 계산했습니다. 설정된 마비
                  쪽은 {SIDE_LABEL[autoSide.from]}입니다.
                </b>
                <div class="small">여러 동작에서 같은 쪽이 1.5배 이상 덜 움직였습니다. 맞는지 확인해 주세요.</div>
              </Notice>
              <button
                class="btn primary block"
                onClick={async () => {
                  await actions.saveProfile({ ...profile, affectedSide: autoSide.to });
                  setAutoSide(null);
                }}
              >
                {SIDE_LABEL[autoSide.to]}이 맞아요 · 설정도 바꾸기
              </button>
              <button
                class="btn block"
                onClick={() => {
                  const from = autoSide.from;
                  keepSide.current = true;
                  setAutoSide(null);
                  finish(from);
                }}
              >
                아니에요 · 설정대로 {SIDE_LABEL[autoSide.from]}으로 계산
              </button>
            </div>
          )}
          {r && suggested && !autoSide && !keepSide.current && (
            <div class="card danger">
              <Notice tone="danger">
                <b>
                  측정해 보니 {SIDE_LABEL[suggested]}이 더 약합니다. 설정된 마비 쪽은 {SIDE_LABEL[profile.affectedSide]}입니다.
                </b>
                <div class="small">마비 쪽이 반대로 설정되면 건강한 쪽을 마비 쪽으로 계산해 수치가 100%를 넘거나 거의 100%로 나옵니다.</div>
              </Notice>
              {isDemo ? (
                <button class="btn primary block" onClick={resetToOwnProfile}>
                  데모 지우고 내 프로필 만들기
                </button>
              ) : (
                <button class="btn primary block" onClick={() => switchSide(suggested)}>
                  마비 쪽을 {SIDE_LABEL[suggested]}으로 바꾸고 다시 계산
                </button>
              )}
            </div>
          )}
          {r && r.status !== 'failed' && moved.length > 0 && (
            <div class="card warn">
              <Notice tone="warn">
                <b>동작 중 머리가 움직여 정확도가 낮을 수 있는 동작</b>
                <div class="small">{moved.map((t) => TASK_LABEL[t as keyof typeof TASK_LABEL]).join(', ')}</div>
              </Notice>
              <button class="btn block" onClick={() => restart(moved)}>
                이 동작만 다시 찍기
              </button>
              <div class="xsmall muted">휴대폰을 세워 두고, 표정을 짓는 동안 고개를 움직이지 않게 해 주세요.</div>
            </div>
          )}
          {r && r.status !== 'failed' && jawOpen && (
            <div class="card warn">
              <Notice tone="warn">
                <b>웃을 때 턱이 벌어졌어요</b>
                <div class="small">{WARNING_LABEL.JAW_OPEN}</div>
              </Notice>
              <button class="btn block" onClick={() => restart(['smile'])}>
                웃기만 다시 찍기
              </button>
            </div>
          )}
          {r && r.status !== 'failed' && prevScored && (
            <div class="card">
              <h3 style={{ margin: '0 0 4px' }}>지난 평가({fmtDate(prevScored.createdAt)})와 비교해 얼굴 움직임이 어떤가요?</h3>
              <p class="xsmall muted" style={{ margin: '0 0 6px' }}>
                느낌대로 골라 주세요(선택). 측정값과 함께 기록되어, 환자가 알아차리는 변화의 크기를 연구하는 데 씁니다.
              </p>
              <div class="row wrap" style={{ gap: '6px' }} role="group" aria-label="느낀 변화">
                {([-3, -2, -1, 0, 1, 2, 3] as const).map((v) => (
                  <button
                    class={`btn sm ${felt === v ? 'primary' : ''}`}
                    aria-pressed={felt === v}
                    onClick={() => setFelt(felt === v ? null : v)}
                  >
                    {CHANGE_FELT_LABEL[v]}
                  </button>
                ))}
              </div>
            </div>
          )}
          {r?.status === 'complete' && !suggested && moved.length === 0 && !jawOpen && (
            <div class="card good">
              <Notice tone="good">
                <b>모든 동작이 정상적으로 측정되었습니다.</b>
              </Notice>
              <button class="btn primary block" onClick={doSave}>
                결과 저장하고 보기
              </button>
            </div>
          )}
          {r?.status === 'complete' && (suggested || moved.length > 0 || jawOpen) && (
            <button class="btn block" onClick={doSave}>
              이대로 저장하고 보기
            </button>
          )}
          {r?.status === 'failed' && (
            <div class="card danger">
              <Notice tone="danger">
                <b>안정 상태 얼굴을 충분히 측정하지 못했습니다.</b>
                <div class="small">
                  {(() => {
                    const i = r.restQuality && topIssue(r.restQuality.issueCounts);
                    return i ? ISSUE_LABEL[i] : '밝은 곳에서 정면을 바라보고 다시 시도해 주세요.';
                  })()}
                </div>
              </Notice>
              <button class="btn primary block" onClick={() => start(mode)}>
                처음부터 다시 측정
              </button>
            </div>
          )}
          {r?.status === 'incomplete' && (
            <div class="card warn">
              <Notice tone="warn">
                <b>다시 측정이 필요한 동작이 있습니다.</b>
              </Notice>
              <ul class="stack small" style={{ margin: 0, paddingLeft: '20px' }}>
                {retry.map((t) => (
                  <li>
                    <b>{TASK_LABEL[t]}</b> — {r.tasks[t] ? WARNING_LABEL.LOW_EFFORT : '얼굴이 잘 보이지 않았습니다.'}
                  </li>
                ))}
              </ul>
              <button class="btn primary block" onClick={() => restart(retry)}>
                해당 동작만 다시 측정
              </button>
              <button
                class="btn block"
                onClick={() => save(r, phase.k === 'result' ? phase.c : null, phase.k === 'result' ? phase.m : null)}
              >
                부분 결과로 저장
              </button>
            </div>
          )}
          {phase.k === 'result' && phase.c && phase.c.status !== 'failed' && (
            <div class="card tight">
              <b class="small">연합운동</b>
              <div class="small ink2">
                {phase.c.findings.length ? `함께 움직이는 곳 ${phase.c.findings.length}군데` : '뚜렷한 연합운동 없음'}
                {(phase.c.mild ?? []).length ? ` · 미세 ${phase.c.mild!.length}군데` : ''}
                {phase.c.missing.length ? ` · 측정 안 된 표정 ${phase.c.missing.length}개` : ''} — 저장하면 얼굴 지도로 볼 수 있습니다.
              </div>
            </div>
          )}
          {r && r.warnings.filter((w) => !HANDLED.has(w.code) && !(jawOpen && w.code === 'JAW_OPEN')).length > 0 && (
            <div class="card tight">
              {r.warnings
                .filter((w) => !HANDLED.has(w.code) && !(jawOpen && w.code === 'JAW_OPEN'))
                .map((w) => (
                  <Notice tone="warn">
                    <span class="small">{WARNING_LABEL[w.code]}</span>
                  </Notice>
                ))}
            </div>
          )}
          <button class="btn ghost block" onClick={() => navigate('/')}>
            저장하지 않고 나가기
          </button>
        </main>
      </>
    );
  }

  const i = 'i' in phase ? phase.i : -1;
  const task = i >= 0 ? queue[i]! : null;
  const q = cam.quality;
  return (
    <>
      <AppBar
        title={task ? stepLabel(task) : '얼굴 위치 맞추기'}
        sub={task ? `${i + 1} / ${queue.length}` : undefined}
        onBack={() => navigate('/')}
      />
      <main class="main bare">
        <div onClick={onStageTap}>
          <CameraStage cam={cam}>
            <div class="hud">
              <div class="chips">
                {q && q.ok && (
                  <span class="chip good">
                    <Icon name="check" /> 좋아요
                  </span>
                )}
                {q?.issues.slice(0, 2).map((x) => (
                  <span class="chip warn">{ISSUE_LABEL[x]}</span>
                ))}
              </div>
              {phase.k === 'align' && (
                <div class="banner">
                  <div class="big">정면을 바라보세요</div>
                  <div class="small">얼굴 윤곽선이 흰색으로 유지되면 자동으로 시작합니다</div>
                  {guiding && (place || ghostShown) && (
                    <div class="small" style={{ marginTop: '4px' }}>
                      {place === 'closer'
                        ? '지난번보다 가까워요 — 폰을 조금 멀리 두세요'
                        : place === 'farther'
                          ? '지난번보다 멀어요 — 폰을 조금 가까이 두세요'
                          : place === 'ok'
                            ? `지난번과 같은 거리예요${ghostShown ? ' · 점선(지난번 얼굴 자리)에 맞추면 더 좋아요' : ''}`
                            : '점선은 지난번 얼굴 자리입니다'}
                    </div>
                  )}
                  <div class="progress">
                    <div style={{ width: `${progress * 100}%` }} />
                  </div>
                </div>
              )}
              {(phase.k === 'countdown' || phase.k === 'record' || phase.k === 'relax') && task && (
                <div class="banner">
                  <div class="big">
                    {phase.k === 'relax'
                      ? '힘을 빼고 편안히'
                      : phase.k === 'record'
                        ? task === 'rest'
                          ? '그대로 편안히'
                          : '가장 크게 지은 채 유지'
                        : stepLabel(task)}
                  </div>
                  {phase.k === 'countdown' && <div class="small">{phase.note ? `${phase.note} · 다시 진행합니다` : stepHow(task)}</div>}
                  {phase.k === 'countdown' && phase.example && isTask(task) && task !== 'rest' && (
                    <div style={{ width: '112px', margin: '8px auto 0' }}>
                      <div class="fsr-thumb">
                        <TaskExampleAnim task={task} affectedSide={profile.affectedSide} />
                      </div>
                      <div class="xsmall" style={{ marginTop: '4px' }}>
                        이렇게 해 보세요
                      </div>
                    </div>
                  )}
                  {phase.k === 'record' && (
                    <div class="progress">
                      <div style={{ width: `${progress * 100}%` }} />
                    </div>
                  )}
                </div>
              )}
            </div>
            {/* With the example the banner is tall: the number moves up so it does not cover the banner. */}
            {phase.k === 'countdown' && phase.ready && <div class={`count${phase.example ? ' top' : ''}`}>{phase.n}</div>}
          </CameraStage>
        </div>
        <div class="taskdots" aria-hidden="true">
          {queue.map((_, k) => (
            <span class={k < i ? 'done' : k === i ? 'now' : ''} />
          ))}
        </div>
        {task && <p class="center ink2">{stepHow(task)}</p>}
        {(phase.k === 'countdown' || phase.k === 'record') && task && task !== 'rest' && (
          <p class="center xsmall muted">화면을 누르면 안내를 건너뛰고 바로 시작하거나, 표정을 지은 채 바로 끝낼 수 있어요.</p>
        )}
      </main>
    </>
  );
}
