/**
 * How long an assessment step records (SRS-USA-013). Patients found the fixed 3.5 s hard: the spoken instruction ran
 * into it, and a slow expression was cut off while a quick one waited. A step now ends once the face has been held
 * near its peak for PACE.holdSec, between minSec and maxSec; rest keeps a fixed length.
 *
 * The analysis takes the strongest frames (≥ 85 % of the peak, up to 7; analyze.ts selectPeakFrames), so ending after a
 * held peak keeps every frame it would use and drops the waiting before and after.
 */
/** Recorded with each assessment (SessionRecord.capture). */
export const CAPTURE_PACE_VERSION = 'CP-0.1.0';

export const PACE = {
  /** Rest records a fixed stretch: there is no peak to wait for. */
  restSec: 2.5,
  minSec: 1.5,
  maxSec: 5,
  /** Seconds held near the peak before the step ends. */
  holdSec: 1,
  /** "Near the peak": this share of the highest movement so far. */
  nearPeak: 0.85,
  /** The peak growing by more than this share starts the hold over (the face is still moving). */
  regrow: 0.05,
  /** Movement must clear the rest step's noise by this many SDs, and this floor (face units), to count as started. */
  moveZ: 4,
  moveFloor: 0.01,
  /** A tap ends the recording only after this long (a tap on arrival would leave nothing to measure). */
  tapAfterSec: 1,
} as const;

export type StopReason = 'plateau' | 'max' | 'tap' | 'fixed';

/** What a step's recording was, for reading the timings back from the data (SRS-USA-013). */
export interface StepCapture {
  ms: number;
  reason: StopReason;
  /** From the start to the first frame within nearPeak of the final peak; null without movement. */
  toPeakMs: number | null;
}

export interface MoveNoise {
  median: number;
  sd: number;
}

const median = (xs: readonly number[]) => {
  const s = [...xs].sort((a, b) => a - b);
  const m = s.length >> 1;
  return s.length % 2 ? s[m]! : (s[m - 1]! + s[m]!) / 2;
};

/** The rest step's expression magnitude: its level and spread (MAD), what a movement has to clear. */
export function moveNoise(mags: readonly number[]): MoveNoise | null {
  if (mags.length < 5) return null;
  const m = median(mags);
  return { median: m, sd: 1.4826 * median(mags.map((x) => Math.abs(x - m))) };
}

export const minMoveFrom = (n: MoveNoise | null): number => Math.max(PACE.moveFloor, n ? n.median + PACE.moveZ * n.sd : 0);

/**
 * Feed it each frame's expression magnitude (null for a frame without a usable face) with the seconds since the
 * recording started; it says when the step is done and how far the hold has come (0–1, for the progress bar).
 */
export class PlateauStop {
  private peak = 0;
  private nearSince: number | null = null;
  /** The peak when the hold began: a face still rising slowly passes it by more than `regrow` and the hold starts over. */
  private holdPeak = 0;
  private readonly samples: { t: number; s: number }[] = [];

  constructor(private readonly minMove: number) {}

  feed(t: number, s: number | null): { done: boolean; hold: number; reason?: StopReason } {
    if (s !== null) {
      this.samples.push({ t, s });
      this.peak = Math.max(this.peak, s);
      const near = this.peak >= this.minMove && s >= PACE.nearPeak * this.peak;
      if (!near) this.nearSince = null;
      else if (this.nearSince === null || this.peak > this.holdPeak * (1 + PACE.regrow)) {
        this.nearSince = t;
        this.holdPeak = this.peak;
      }
    }
    const held = this.nearSince === null ? 0 : t - this.nearSince;
    const hold = Math.min(1, held / PACE.holdSec);
    if (t >= PACE.maxSec) return { done: true, hold, reason: 'max' };
    if (t >= PACE.minSec && held >= PACE.holdSec) return { done: true, hold: 1, reason: 'plateau' };
    return { done: false, hold };
  }

  /** Seconds to the first frame within nearPeak of the final peak (onset-to-peak), or null if the face never moved. */
  timeToPeak(): number | null {
    if (this.peak < this.minMove) return null;
    const first = this.samples.find((x) => x.s >= PACE.nearPeak * this.peak);
    return first ? first.t : null;
  }
}
